    type: "wildlife-area",
    parent: "LB-AS",
    coords: [35.98, 34.30],
    name: { de: "Naturreservat Horsh Ehden", hu: "Horsh Ehden természetvédelmi terület", ro: "Rezervația naturală Horsh Ehden", en: "Horsh Ehden Nature Reserve"},
    image: "/poi-images/horsh-ehden-reserve-life-v2.webp",
    description: { de: "Ein isoliertes Waldgebiet im Norden des Libanon, das für seine außergewöhnliche botanische Vielfalt bekannt ist.", hu: "Egy elszigetelt erdőterület Észak-Libanonban, amely kivételes botanikai sokféleségéről ismert.", ro: "O zonă forestieră izolată din nordul Libanului, cunoscută pentru diversitatea sa botanică excepțională.", en: "An isolated forest area in northern Lebanon known for its exceptional botanical diversity." , es: "Un área forestal aislada en el norte del Líbano, conocida por su extraordinaria diversidad botánica.", pt: "Uma área florestal isolada no norte do Líbano, conhecida pela sua extraordinária diversidade botânica.", fr: "Une zone forestière isolée au nord du Liban, connue pour son extraordinaire diversité botanique."},
    facts: {
      de: ["Beherbergt über 1000 Pflanzenarten.", "Wichtiger Zufluchtsort für seltene Schmetterlinge."],
      hu: ["Több mint 1000 növényfajnak ad otthont.", "Ritka lepkék fontos menedékhelye."],
      ro: ["Găzduiește peste 1000 de specii de plante.", "Un refugiu important pentru fluturii rari."],
      en: ["Home to over 1000 plant species.", "An important refuge for rare butterflies."],
      es: ["Alberga más de 1000 especies de plantas.", "Refugio importante para mariposas raras."],
      pt: ["Alberga mais de 1000 espécies de plantas.", "Refúgio importante para borboletas raras."],
      fr: ["Abrite plus de 1000 espèces de plantes.", "Refuge important pour des papillons rares."],
    }, image: "/poi-images/horsh-ehden-reserve-life-v2.webp",
    descriptionAdvanced: {
      de: "Das Naturschutzgebiet Horsh Ehden liegt an den Nordwesthängen des Libanongebirges und umfasst eine Waldfläche, die für ihre hohe botanische Diversität bekannt ist. Auf einer Höhe von 1200 bis 2000 Metern gelegen, beherbergt der Wald libanesische Zedern, Kilikische Tannen und eine große Anzahl wilder Apfelbäume. Das Mikroklima der Region fördert das Wachstum von mehr als tausend Pflanzenarten, wovon viele nur im Libanon vorkommen. Die Tierwelt ist durch seltene Säugetiere wie den bedrohten anatolischen Leoparden, Luchse und Stachelschweine geprägt. Das 1992 eingerichtete Reservat dient dem Schutz dieses einzigartigen Ökosystems vor Abholzung und Urbanisierung. Besucher nutzen das gut ausgebaute Wegenetz für Wanderungen, Vogelbeobachtungen und zur Erkundung der alpinen Landschaft, die im Winter tief verschneit ist.",
      hu: "A Horsh Ehden Természetvédelmi Terület a Libanon-hegység északnyugati lejtőin található, és egy olyan erdőséget foglal magába, amely kiemelkedő botanikai sokféleségéről ismert. Az 1200 és 2000 méter közötti tengerszint feletti magasságban elterülő erdő libanoni cédrusoknak, kilikiai jegenyefenyőknek és vad almafáknak ad otthont. A régió mikroklímája több mint ezer növényfaj fejlődését támogatja, amelyek közül sok csak Libanonban található meg. Az állatvilágot ritka emlősök, például hiúzok és sülök jelenléte gazdagítja. Az 1992-ben létrehozott rezervátum ezt az egyedülálló ökoszisztémát védi az erdőirtás és az urbanizáció ellen. A látogatók a jól kiépített ösvényhálózatot túrázásra, madármegfigyelésre és a télen hóborította alpesi táj felfedezésére használják.",
      ro: "Rezervația Naturală Horsh Ehden este situată pe versanții nord-vestici ai lanțului muntos Liban și cuprinde o pădure cunoscută pentru diversitatea sa botanică ridicată. Aflată la o altitudine cuprinsă între 1200 și 2000 de metri, pădurea găzduiește cedri de Liban, brazi de Cilicia și un număr mare de meri sălbatici. Microclimatul regiunii favorizează creșterea a peste o mie de specii de plante, multe dintre ele endemice Libanului. Fauna sălbatică se remarcă prin prezența mamiferelor rare, cum ar fi râșii și porcii spinoși. Rezervația, înființată în 1992, servește la protejarea acestui ecosistem unic împotriva defrișărilor și urbanizării. Vizitatorii folosesc rețeaua bine dezvoltată de trasee pentru drumeții, observarea păsărilor și explorarea peisajului alpin, acoperit cu zăpadă iarna.",
      en: "The Horsh Ehden Nature Reserve is situated on the northwestern slopes of the Mount Lebanon range, protecting a forest renowned for its high botanical diversity. Ranging from 1,200 to 2,000 meters in altitude, the forest is home to Lebanon cedars, Cilician firs, and numerous wild apple trees. The area's microclimate supports the growth of over a thousand plant species, many of which are endemic to Lebanon. The wildlife is characterized by rare mammals, including lynxes and porcupines. Established in 1992, the reserve is dedicated to safeguarding this unique ecosystem from deforestation and urbanization. Visitors utilize the extensive trail network for hiking, bird watching, and exploring the alpine landscape, which experiences heavy snowfall during the winter months.",
      es: "La reserva natural de Horsh Ehden está situada en las laderas noroccidentales de las montañas del Líbano y comprende una zona forestal conocida por su elevada diversidad botánica. Situado a una altitud de entre 1200 y 2000 metros, el bosque alberga cedros del Líbano, abetos de Cilicia y una gran cantidad de manzanos silvestres. El microclima de la región favorece el crecimiento de más de mil especies vegetales, muchas de las cuales solo se encuentran en el Líbano. La fauna se caracteriza por mamíferos raros como el amenazado leopardo de Anatolia, linces y puercoespines. La reserva, creada en 1992, sirve para proteger este ecosistema único de la deforestación y la urbanización. Los visitantes aprovechan la red de senderos bien acondicionados para practicar senderismo, observación de aves y explorar el paisaje alpino, que en invierno queda cubierto por la nieve.",
      pt: "A reserva natural de Horsh Ehden está situada nas encostas noroeste das montanhas do Líbano e compreende uma área florestal conhecida pela sua elevada diversidade botânica. Situada a uma altitude de 1200 a 2000 metros, a floresta alberga cedros do Líbano, abetos da Cilícia e um grande número de macieiras bravas. O microclima da região favorece o crescimento de mais de mil espécies de plantas, muitas das quais só ocorrem no Líbano. A vida selvagem é caracterizada por mamíferos raros como o ameaçado leopardo-da-Anatólia, linces e porcos-espinhos. A reserva, estabelecida em 1992, serve para proteger este ecossistema único da desflorestação e da urbanização. Os visitantes utilizam a rede de trilhos bem desenvolvida para caminhadas, observação de aves e para explorar a paisagem alpina, que fica coberta de neve no inverno.",
      fr: "La réserve naturelle de Horsh Ehden est située sur les versants nord-ouest de la chaîne du Liban et comprend une zone forestière réputée pour sa grande diversité botanique. Située à une altitude de 1200 à 2000 mètres, la forêt abrite des cèdres du Liban, des sapins de Cilicie et un grand nombre de pommiers sauvages. Le microclimat de la région favorise la croissance de plus de mille espèces végétales, dont beaucoup ne se trouvent qu'au Liban. La faune est marquée par des mammifères rares tels que le léopard d'Anatolie, menacé, des lynx et des porcs-épics. Créée en 1992, la réserve sert à protéger cet écosystème unique contre la déforestation et l'urbanisation. Les visiteurs profitent du réseau de sentiers bien aménagés pour la randonnée, l'observation des oiseaux et l'exploration du paysage alpin, qui est profondément enneigé en hiver.",
    },
