      hu: ["1200 és 2000 méter közötti magasság", "Több mint 1000 növényfaj található itt", "Kilikiai jegenyefenyőket és cédrusokat véd", "Ritka hiúzok otthona", "1992-ben alapították", "Népszerű a téli hótalpas túrákhoz"],
