      pt: ["Abrange as maiores praias de areia restantes do Líbano", "Área de cerca de 3,8 quilómetros quadrados", "Contém nascentes artesianas históricas", "Importante local de reprodução para tartarugas-comum", "Dividido em três zonas específicas", "Reserva natural oficial desde 1998"],
