    coords: [35.88, 33.83],
    name: { de: "Weingüter der Bekaa-Ebene", hu: "A Bekaa-völgy borászatai", ro: "Podgoriile din Valea Bekaa", en: "Bekaa Valley Vineyards"},
    image: "/poi-images/bekaa-vineyards-life-v2.webp",
    description: { de: "Die historischen Weinanbaugebiete des Libanon, wo jahrhundertealte Traditionen auf moderne Weinbautechniken treffen.", hu: "Libanon történelmi bortermelő vidékei, ahol az évszázados hagyományok találkoznak a modern szőlészeti technikákkal.", ro: "Zonele istorice de cultivare a viței de vie din Liban, unde tradițiile seculare se întâlnesc cu tehnicile viticole moderne.", en: "The historic wine-growing regions of Lebanon, where centuries-old traditions meet modern viticultural techniques." , es: "Las históricas regiones vinícolas del Líbano, donde las tradiciones milenarias se encuentran con las técnicas modernas de viticultura.", pt: "As históricas regiões vinícolas do Líbano, onde tradições seculares se encontram com técnicas modernas de viticultura.", fr: "Les régions viticoles historiques du Liban, où les traditions séculaires rencontrent les techniques modernes de viticulture."},
    facts: {
      de: ["Produziert die meisten der libanesischen Weine.", "Die Anbauhöhe liegt bei über 1000 Metern."],
      hu: ["Itt készül a libanoni borok nagy része.", "A termesztési magasság több mint 1000 méter."],
      ro: ["Produce majoritatea vinurilor libaneze.", "Altitudinea de cultivare este de peste 1000 de metri."],
      en: ["Produces most of the Lebanese wines.", "The cultivation altitude is over 1000 meters."],
      es: ["Produce la mayoría de los vinos libaneses.", "La altitud de cultivo es de más de 1000 metros."],
      pt: ["Produz a maioria dos vinhos libaneses.", "A altitude de cultivo é superior a 1000 metros."],
      fr: ["Produit la majeure partie des vins libanais.", "L'altitude de culture dépasse les 1000 mètres."],
    }, image: "/poi-images/bekaa-vineyards-life-v2.webp",
    descriptionAdvanced: {
      de: "Die Weinberge der Bekaa-Ebene bilden das Herzstück des libanesischen Weinbaus und blicken auf eine Jahrtausende alte Tradition zurück, die bis zu den Phöniziern reicht. Auf einer Höhe von rund 1000 Metern über dem Meeresspiegel profitieren die Reben von einem außergewöhnlichen Mikroklima mit über 300 Sonnentagen im Jahr und kühlen, trockenen Nächten. Die kalkhaltigen Ton- und Kiesböden der Ebene bieten ideale Bedingungen für den Anbau klassischer französischer Rebsorten wie Cabernet Sauvignon, Cinsault, Carignan und Syrah, aber auch für einheimische Weißweinsorten wie Obeidi und Merwah. Zahlreiche namhafte Weingüter, wie Château Ksara und Château Musar, kultivieren hier ihre international ausgezeichneten Weine. Diese Weinregion verbindet moderne önologische Techniken mit historischem Erbe, was sie zu einem zentralen Ort des Agrotourismus im Libanon macht.",
      hu: "A Bekaa-völgy szőlőültetvényei a libanoni borászat szívét jelentik, és a föníciaiak koráig visszanyúló, több ezer éves hagyományokra épülnek. A tengerszint felett körülbelül 1000 méteres magasságban a szőlőtőkék különleges mikroklímát élveznek, évente több mint 300 napsütéses nappal és hűvös, száraz éjszakákkal. A síkság meszes-agyagos és kavicsos talaja ideális feltételeket biztosít mind a klasszikus francia fajták – mint a Cabernet Sauvignon, a Cinsault vagy a Syrah –, mind a helyi fehérboros fajták (Obeidi és Merwah) termesztéséhez. Számos neves borászat, például a Château Ksara és a Château Musar, itt készíti nemzetközileg is elismert borait. A régió sikeresen ötvözi a modern borászati technikákat a történelmi örökséggel, amivel a libanoni agroturizmus központjává vált.",
      ro: "Podgoriile din Valea Bekaa reprezintă inima viticulturii libaneze, având o tradiție milenară care datează de la fenicieni. Aflate la o altitudine de aproximativ 1000 de metri, viile beneficiază de un microclimat excepțional, cu peste 300 de zile însorite pe an și nopți răcoroase. Solurile calcaroase și pietrișoase oferă condiții ideale pentru cultivarea soiurilor clasice franceze, precum Cabernet Sauvignon, Cinsault și Syrah, dar și a soiurilor locale de struguri albi precum Obeidi și Merwah. Numeroase crame de renume, cum ar fi Château Ksara și Château Musar, își produc aici vinurile apreciate la nivel internațional. Această regiune viticolă combină tehnologiile oenologice moderne cu moștenirea istorică, devenind un centru al agroturismului.",
      en: "The vineyards of the Bekaa Valley form the heartland of Lebanese viticulture, boasting a millennia-old tradition that dates back to the Phoenicians. Situated at an altitude of approximately 1,000 meters above sea level, the vines benefit from an exceptional microclimate with over 300 days of sunshine annually and cool, dry nights. The valley's calcareous clay and gravel soils provide ideal conditions for cultivating classic French grape varieties such as Cabernet Sauvignon, Cinsault, Carignan, and Syrah, alongside indigenous white grapes like Obeidi and Merwah. Renowned estates, including Château Ksara and Château Musar, produce their internationally acclaimed wines here. This winemaking region seamlessly integrates modern oenological practices with profound historical heritage, making it a primary destination for agritourism.",
      es: "Los viñedos del valle de la Bekaa constituyen el corazón de la viticultura libanesa y cuentan con una tradición milenaria que se remonta a los fenicios. A una altitud de unos 1000 metros sobre el nivel del mar, las vides se benefician de un microclima excepcional con más de 300 días de sol al año y noches frescas y secas. Los suelos calcáreos de arcilla y grava de la llanura ofrecen condiciones ideales para el cultivo de variedades clásicas francesas como Cabernet Sauvignon, Cinsault, Carignan y Syrah, así como para variedades blancas autóctonas como Obeidi y Merwah. Numerosas bodegas de renombre, como Château Ksara y Château Musar, cultivan aquí sus vinos galardonados internacionalmente. Esta región vinícola combina técnicas enológicas modernas con el patrimonio histórico, convirtiéndola en un lugar central para el agroturismo en el Líbano.",
      pt: "Os vinhedos do Vale do Bekaa constituem o coração da viticultura libanesa e contam com uma tradição milenar que remonta aos fenícios. A uma altitude de cerca de 1000 metros acima do nível do mar, as videiras beneficiam de um microclima excecional com mais de 300 dias de sol por ano e noites frescas e secas. Os solos calcários de argila e cascalho da planície oferecem condições ideais para o cultivo de castas francesas clássicas como Cabernet Sauvignon, Cinsault, Carignan e Syrah, mas também para castas brancas nativas como Obeidi e Merwah. Inúmeras vinícolas de renome, como Château Ksara e Château Musar, cultivam aqui os seus vinhos premiados internacionalmente. Esta região vinícola combina técnicas enológicas modernas com património histórico, tornando-a um local central para o agroturismo no Líbano.",
      fr: "Les vignobles de la plaine de la Bekaa constituent le cœur de la viticulture libanaise et s'appuient sur une tradition millénaire remontant aux Phéniciens. À une altitude d'environ 1000 mètres, les vignes bénéficient d'un microclimat exceptionnel avec plus de 300 jours de soleil par an et des nuits fraîches. Les sols calcaires, argileux et graveleux offrent des conditions idéales pour la culture de cépages français classiques comme le Cabernet Sauvignon, le Cinsault, le Carignan et la Syrah, ainsi que pour des cépages blancs indigènes tels que l'Obeidi et le Merwah. De nombreux domaines de renom, comme Château Ksara et Château Musar, y produisent leurs vins internationalement primés. Cette région viticole allie techniques œnologiques modernes et héritage historique, ce qui en fait un haut lieu de l'agrotourisme au Liban.",
    },
